import pandas as pd

invoices = pd.read_csv('/app/dataset/invoices.csv')

for seller_id, group in invoices.groupby('seller_id'):
    if len(group) >= 10:
        counts = group['net_amount'].apply(lambda x: x % 1 == 0).value_counts(normalize=True)
        if counts.get(True, 0) > 0.9:
            print(f"Seller {seller_id}: {counts.get(True, 0)*100:.1f}% integer amounts")
